import React, { useCallback, useEffect, useState } from 'react';
import api from '../../api/axios';

const REFRESH_MS = 30000;
const BAR_AREA_PX = 120; // height of the tallest bar

function describeError(err) {
  const status = err?.response?.status;
  if (!err?.response) {
    return `Can't reach the API at ${api.defaults.baseURL}. Is the Laravel server running?`;
  }
  if (status === 401) return 'Your session has expired. Sign out and log in again.';
  if (status === 403) return "This account doesn't have administrator access.";
  return `The server returned an error (${status}). Check the Laravel log for details.`;
}

function BarChart({ rows, series }) {
  const max = Math.max(1, ...rows.flatMap((d) => series.map((s) => d[s.key] || 0)));

  return (
    <div className="bar-chart">
      {rows.map((d) => (
        <div className="bar-col" key={d.date}>
          <div className="bar-track">
            {series.map((s) => {
              const value = d[s.key] || 0;
              const height = value > 0 ? Math.max(3, Math.round((value / max) * BAR_AREA_PX)) : 0;
              return (
                <div className="bar-wrap" key={s.key}>
                  <span className="bar-value">{value > 0 ? value : ''}</span>
                  <div
                    className={`bar ${s.className || ''}`}
                    style={{ height: `${height}px` }}
                    title={`${s.label}: ${value} on ${d.date}`}
                  />
                </div>
              );
            })}
          </div>
          <span className="bar-label">{d.date.slice(5)}</span>
        </div>
      ))}
    </div>
  );
}

export default function Dashboard() {
  const [summary, setSummary] = useState(null);
  const [overTime, setOverTime] = useState([]);
  const [successVsFailed, setSuccessVsFailed] = useState([]);
  const [registrations, setRegistrations] = useState([]);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const [updatedAt, setUpdatedAt] = useState(null);

  const load = useCallback(async () => {
    const results = await Promise.allSettled([
      api.get('/admin/analytics/summary'),
      api.get('/admin/analytics/login-attempts-over-time'),
      api.get('/admin/analytics/success-vs-failed'),
      api.get('/admin/analytics/registration-statistics'),
    ]);

    // Keep whatever loaded; only replace a section when its request succeeded.
    if (results[0].status === 'fulfilled') setSummary(results[0].value.data);
    if (results[1].status === 'fulfilled') setOverTime(results[1].value.data);
    if (results[2].status === 'fulfilled') setSuccessVsFailed(results[2].value.data);
    if (results[3].status === 'fulfilled') setRegistrations(results[3].value.data);

    const firstFailure = results.find((r) => r.status === 'rejected');
    setError(firstFailure ? describeError(firstFailure.reason) : '');
    setUpdatedAt(new Date());
    setLoading(false);
  }, []);

  useEffect(() => {
    load();
    const id = setInterval(load, REFRESH_MS);
    return () => clearInterval(id);
  }, [load]);

  const cards = [
    { label: 'Total Registered Users', value: summary?.total_registered_users },
    { label: 'Total Website Visits', value: summary?.total_website_visits },
    { label: 'Total Login Attempts', value: summary?.total_login_attempts },
    { label: 'Successful Logins', value: summary?.successful_logins },
    { label: 'Failed Logins', value: summary?.failed_logins },
    { label: 'Active Users', value: summary?.active_users },
  ];

  return (
    <div>
      <div className="dash-header">
        <div>
          <h1>Dashboard</h1>
          <p className="muted small">
            {updatedAt ? `Updated ${updatedAt.toLocaleTimeString()}` : 'Loading…'} · refreshes every 30s
          </p>
        </div>
        <button type="button" className="refresh-btn" onClick={load}>Refresh</button>
      </div>

      {error && <div className="auth-error">{error}</div>}

      <div className="summary-grid">
        {cards.map((c) => (
          <div className="summary-card" key={c.label}>
            <div className="summary-value">{c.value ?? '—'}</div>
            <div className="summary-label">{c.label}</div>
          </div>
        ))}
      </div>

      <div className="chart-grid">
        <div className="chart-card">
          <h3>Login Attempts Over Time (14d)</h3>
          {loading ? (
            <p className="muted">Loading…</p>
          ) : (
            <BarChart rows={overTime} series={[{ key: 'total', label: 'Attempts' }]} />
          )}
        </div>

        <div className="chart-card">
          <h3>Successful vs Failed Logins (14d)</h3>
          <div className="chart-legend">
            <span><i className="legend-dot success" />Successful</span>
            <span><i className="legend-dot failed" />Failed</span>
          </div>
          {loading ? (
            <p className="muted">Loading…</p>
          ) : (
            <BarChart
              rows={successVsFailed}
              series={[
                { key: 'successful', label: 'Successful', className: 'success' },
                { key: 'failed', label: 'Failed', className: 'failed' },
              ]}
            />
          )}
        </div>

        <div className="chart-card wide">
          <h3>New Registrations (14d)</h3>
          {loading ? (
            <p className="muted">Loading…</p>
          ) : (
            <BarChart rows={registrations} series={[{ key: 'total', label: 'Registrations' }]} />
          )}
        </div>
      </div>
    </div>
  );
}
